export function getCharacterById(id: number): Character | undefined {
  return CHARACTERS.find((c) => c.id === id);
}

export function getCharactersByElement(element: Character["element"]): Character[] {
  return CHARACTERS.filter((c) => c.element === element);
}

export function getCharactersByPath(path: Character["path"]): Character[] {
  return CHARACTERS.filter((c) => c.path === path);
}
